function cvGuardaFech(k,v){var m=cvFechMapa();m[k]=v?1:0;try{localStorage.setItem('cv_fech',JSON.stringify(m));}catch(e){}}

// ===== PRODUTO SEM VENDA — v87 =====
var psvCache=null,psvAba=null,psvNao={};
var PSV_ABAS={ALERTA:'ALERTA','30':'30 DIAS','60':'60 DIAS'};
function irPSV(){
  pararCamera();$('faixaPSV').textContent='PRODUTO SEM VENDA · '+quem;mostrar('tPSV');
  try{psvCache=JSON.parse(localStorage.getItem('ci_psv')||'null');}catch(e){}
  renderPSV();carregarPSV();
}
function carregarPSV(){
  api({acao:'semVenda',quem:quem}).then(function(r){
    if(r&&r.ok){psvCache={abas:r.abas||[],tudo:!!r.tudo,hist:Number(r.hist)||0,itens:r.itens||[]};try{localStorage.setItem('ci_psv',JSON.stringify(psvCache));}catch(e){}renderPSV();}
    else if(r&&r.erro){toast(r.erro,'err');}
  }).catch(function(){});
}
function psvAbasOk(){return ['ALERTA','30','60'].filter(function(a){return psvCache&&psvCache.abas.indexOf(a)>=0;});}
function psvCont(){
  var tabs=$('psvTabs');tabs.innerHTML='';
  psvAbasOk().forEach(function(a){
    var n=a==='ALERTA'&&psvCache.hist<7?0:psvCache.itens.filter(function(i){return i.aba===a&&!i.resp;}).length;
    var b=document.createElement('button');b.textContent=PSV_ABAS[a]+(n?' ('+n+')':'');b.className=a===psvAba?'on':'';
    b.onclick=function(){if(psvAba===a)return;psvAba=a;renderPSV();try{window.scrollTo(0,0);}catch(e){}};tabs.appendChild(b);
  });
  var its=psvCache.itens.filter(function(i){return i.aba===psvAba;}),ok=its.filter(function(i){return i.resp;}).length;
  $('psvProg').textContent=its.length&&!(psvAba==='ALERTA'&&psvCache.hist<7)?ok+' / '+its.length+' respondidos':'';
}
function renderPSV(){
  var box=$('psvLista');box.innerHTML='';
  if(!psvCache){$('psvTabs').innerHTML='';box.innerHTML='<p class="dica">Carregando…</p>';return;}
  var abas=psvAbasOk();
  if(!abas.length){$('psvTabs').innerHTML='';box.innerHTML='<p class="dica vazio">Nenhuma lista liberada para você.<br>Peça ao Celio.</p>';return;}
  if(abas.indexOf(psvAba)<0)psvAba=abas[0];
  psvCont();
  var tudo=psvCache.tudo;
  if(psvAba==='ALERTA'){
    $('psvTit').textContent='Vende todo dia e parou de vender';
    $('psvDica').innerHTML='produto que vende todo dia, tem saldo no sistema e está há dias sem vender. veja se está na gôndola e responda.';
    if(psvCache.hist<7){box.innerHTML='<p class="dica vazio">🚧 em construção — aguardando histórico de vendas<br><small>'+psvCache.hist+' de 7 dias de histórico</small></p>';return;}
  }else{
    $('psvTit').textContent='Sem venda há '+psvAba+' dias';
    $('psvDica').innerHTML='produto com saldo no sistema que não vendeu nada nos últimos '+psvAba+' dias. veja se está na gôndola e responda.';
  }
  var its=psvCache.itens.filter(function(i){return i.aba===psvAba;});
  if(!its.length){box.innerHTML='<p class="dica vazio">Nada nesta lista. 👍</p>';return;}
  function ord(a,b){return String(a.local||'~').localeCompare(String(b.local||'~'))||(a.resp?1:0)-(b.resp?1:0)||String(a.desc).localeCompare(String(b.desc));}
  var grupos={},ordem=[];
  its.forEach(function(i){var g=tudo?String(i.quem||'Ney').toUpperCase():'MINHA LISTA';if(!grupos[g]){grupos[g]=[];ordem.push(g);}grupos[g].push(i);});
  ordem.sort();
  ordem.forEach(function(g){psvBloco(box,g,grupos[g].sort(ord),tudo);});
}
// cada bloco encolhe/abre ao tocar no título (mesma lógica do Validades); os itens só são montados quando o bloco abre
function psvBloco(box,tit,lista,tudo){
  var pend=lista.filter(function(i){return !i.resp;}).length,k='psv'+psvAba+'|'+tit,m=cvFechMapa(),fech=m[k]!==undefined?!!m[k]:(tudo&&lista.length>40);
  var hd=document.createElement('div');hd.className='grp';hd.innerHTML='<span>'+esc(tit)+' ('+pend+(pend!==lista.length?' de '+lista.length:'')+')</span><span class="sx">'+(fech?'▸':'▾')+'</span>';box.appendChild(hd);
  var ul=document.createElement('ul');ul.className='psv';box.appendChild(ul);var cheio=false;
  function encher(){if(cheio)return;cheio=true;var ult=null;lista.forEach(function(it){var lc=it.local||'sem local no cadastro';if(lc!==ult){ult=lc;var s=document.createElement('div');s.className='loc';s.textContent='📍 '+lc;ul.appendChild(s);}ul.appendChild(psvItem(it));});}
  if(fech)ul.style.display='none';else encher();
  hd.onclick=function(){var f=ul.style.display!=='none';if(!f)encher();ul.style.display=f?'none':'';hd.querySelector('.sx').textContent=f?'▸':'▾';cvGuardaFech(k,f);};
}
function psvNum(v){return String(v==null?'':v).replace('.',',');}
function psvItem(it){
  var li=document.createElement('li');
  var info='<div class="d"><span class="tag'+(it.resp?' ok':'')+'">'+(it.resp?'OK':esc(it.dias)+' DIAS')+'</span>'+esc(it.desc)+'</div>'+
    '<div class="m">SKU '+esc(it.sku)+(it.media&&Number(String(it.media).replace(',','.'))>0?' · média '+esc(psvNum(it.media))+'/dia':'')+' · saldo <b>'+esc(psvNum(it.saldo))+'</b>'+(it.fam?' · família '+esc(it.fam):'')+(psvCache.tudo&&it.quem?' · '+esc(it.quem):'')+'</div>';
  if(it.resp){
    li.className='feito';
    li.innerHTML=info+'<div class="m"><b>'+esc(it.resp)+'</b>'+(it.motivo?': '+esc(it.motivo):'')+'<br>'+esc(it.por)+' · '+esc(it.hora)+'</div><button class="desf">DESFAZER</button>';
    var bd=li.querySelector('.desf');bd.onclick=function(){psvResp(it,'DESFAZER','',bd,li);};return li;
  }
  if(!psvNao[it.id]){
    li.innerHTML=info+'<div class="bts"><button class="sim">ESTÁ NA GÔNDOLA</button><button class="nao">NÃO ESTÁ</button></div>';
    var bs=li.querySelector('.sim');bs.onclick=function(){psvResp(it,'GONDOLA','',bs,li);};
    li.querySelector('.nao').onclick=function(){vibra();psvNao[it.id]=1;li.replaceWith(psvItem(it));};
    return li;
  }
  li.innerHTML=info+'<div class="pq">Não estava na gôndola. O que aconteceu?</div><div class="bts"><button class="r">REPUS AGORA</button><button class="nao e">NÃO TEM NO ESTOQUE</button></div><div class="bts"><button class="sec o">OUTRO</button><button class="sec v">VOLTAR</button></div><div class="outro" style="display:none"><input type="text" maxlength="80" placeholder="o que aconteceu? (curto)"><button>SALVAR</button></div>';
  var br=li.querySelector('.r'),be=li.querySelector('.e'),bo=li.querySelector('.o'),bv=li.querySelector('.v'),ou=li.querySelector('.outro'),inp=ou.querySelector('input'),bsv=ou.querySelector('button');
  br.onclick=function(){psvResp(it,'REPUS','',br,li);};
  be.onclick=function(){psvResp(it,'SEMESTOQUE','',be,li);};
  bo.onclick=function(){ou.style.display='flex';inp.focus();};
  bv.onclick=function(){delete psvNao[it.id];li.replaceWith(psvItem(it));};
  bsv.onclick=function(){var t=inp.value.trim();if(!t){toast('Escreva o que aconteceu','err');inp.focus();return;}psvResp(it,'OUTRO',t,bsv,li);};
  inp.addEventListener('keydown',function(e){if(e.key==='Enter')bsv.click();});
  return li;
}
function psvResp(it,resp,motivo,b,li){
  if(resp==='DESFAZER'&&b.dataset.c!=='1'){b.dataset.c='1';b.textContent='DESFAZER? TOQUE DE NOVO';setTimeout(function(){b.dataset.c='';b.textContent='DESFAZER';},3000);return;}
  vibra();var tx=b.textContent;b.textContent='…';b.disabled=true;
  api({acao:'psvResponder',quem:quem,token:token,id:it.id,resposta:resp,motivo:motivo}).then(function(r){
    if(r&&r.ok){
      delete psvNao[it.id];
      if(resp==='DESFAZER'){it.resp='';it.motivo='';it.por='';it.hora='';toast('Voltou para a lista','ok');}
      else{it.resp=r.resposta;it.motivo=motivo;it.por=quem;it.hora=r.hora;toast('Registrado','ok');}
      try{localStorage.setItem('ci_psv',JSON.stringify(psvCache));}catch(e){}
      li.replaceWith(psvItem(it));psvCont();return;
    }
    b.disabled=false;b.textContent=tx;
    if(r&&r.reauth){toast('Sessão expirada — digite o PIN de novo','err');try{localStorage.removeItem('ci_token');}catch(e){}irPin();return;}
    toast('Não deu: '+(r&&r.erro||''),'err');
  }).catch(function(){b.disabled=false;b.textContent=tx;toast('Sem internet — tente de novo','err');});
}
